use core::net::SocketAddr;
use std::io::{BufRead, BufReader};
use std::process;

use command_fds::CommandFdExt;

/// The file descriptor number used for workerd's `--control-fd`.
const CONTROL_FD: i32 = 3;

/// The path to the Cap'n Proto config file generated by the build script.
const WORKERD_CONFIG_PATH: &str = env!("WORKERD_CONFIG_PATH");

pub(super) struct Workerd {
    pub(super) addr: SocketAddr,
    child: process::Child,
}

impl Workerd {
    /// Spawns a `workerd serve` process which gets killed when the returned
    /// [`Workerd`] is dropped.
    pub(super) fn spawn() -> Self {
        let (read_end, write_end) =
            os_pipe::pipe().expect("failed to create pipe");

        let child = process::Command::new("workerd")
            .args(["serve", WORKERD_CONFIG_PATH])
            .args(["--control-fd", &CONTROL_FD.to_string()])
            .stdin(process::Stdio::null())
            .stdout(process::Stdio::null())
            .stderr(process::Stdio::piped())
            .fd_mappings(vec![command_fds::FdMapping {
                parent_fd: write_end.into(),
                child_fd: CONTROL_FD,
            }])
            .expect("failed to set up fd mappings")
            .spawn()
            .expect("failed to spawn workerd");

        // Read the control message to discover the listening port.
        //
        // workerd writes JSON lines like:
        //   {"event":"listen","socket":"http","port":49152}
        let mut reader = BufReader::new(read_end);
        let mut line = String::new();

        reader
            .read_line(&mut line)
            .expect("failed to read control message from workerd");

        let msg: serde_json::Value = serde_json::from_str(line.trim())
            .unwrap_or_else(|err| {
                panic!(
                    "failed to parse workerd control message {line:?}: {err}"
                )
            });

        assert_eq!(
            msg["event"].as_str(),
            Some("listen"),
            "unexpected control message: {msg}"
        );

        let port = msg["port"]
            .as_u64()
            .unwrap_or_else(|| panic!("missing port in control message: {msg}"))
            as u16;

        Self { addr: SocketAddr::from(([127, 0, 0, 1], port)), child }
    }
}

impl Drop for Workerd {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}
